class nsFrameList{public:using Slice=std::vector<nsIFrame*>;Slice frames,lastInserted;nsFrameList()=default;nsFrameList(nsIFrame*first,nsIFrame*last){assert(first==last);frames.push_back(first);}bool IsEmpty()const{return frames.empty();}nsIFrame*FirstChild()const{return frames.empty()?nullptr:frames.front();}nsIFrame*LastChild()const{return frames.empty()?nullptr:frames.back();}nsIFrame*RemoveFirstChild(){auto*f=FirstChild();if(f)frames.erase(frames.begin());return f;}void InsertFrame(nsIFrame*parent,nsIFrame*previous,nsIFrame*frame){auto at=previous?std::find(frames.begin(),frames.end(),previous)+1:frames.begin();assert(at<=frames.end());frames.insert(at,frame);if(parent)frame->parent=parent;}const Slice&InsertFrames(nsIFrame*parent,nsIFrame*previous,nsFrameList&&other){lastInserted=other.frames;for(auto*f:other.frames){InsertFrame(parent,previous,f);previous=f;}other.frames.clear();return lastInserted;}const Slice&AppendFrames(nsIFrame*parent,nsFrameList&&other){return InsertFrames(parent,LastChild(),std::move(other));}};
